class Solution {
public:
    long long countOperationsToEmptyArray(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> bit(n + 1, 0);
        auto update = [&](int idx, int delta) {
            for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
        };
        auto query = [&](int idx) {
            int s = 0;
            for (; idx > 0; idx -= idx & -idx) s += bit[idx];
            return s;
        };
        for (int i = 1; i <= n; i++) update(i, 1);
        std::vector<int> order(n);
        std::iota(order.begin(), order.end(), 0);
        std::sort(order.begin(), order.end(), [&](int a, int b) {
            return nums[a] < nums[b];
        });
        long long ans = 0;
        int curr = 1;
        for (int target : order) {
            int t = target + 1;
            if (t >= curr) {
                ans += query(t) - query(curr - 1);
            } else {
                ans += query(n) - query(curr - 1) + query(t);
            }
            update(t, -1);
            curr = t;
        }
        return ans;
    }
};

class Solution {
    public long countOperationsToEmptyArray(int[] nums) {
        int n = nums.length;
        int[] bit = new int[n + 1];
        for (int i = 1; i <= n; i++) update(bit, n, i, 1);
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(a -> nums[a]));
        long ans = 0;
        int curr = 1;
        for (int target : order) {
            int t = target + 1;
            if (t >= curr) {
                ans += query(bit, t) - query(bit, curr - 1);
            } else {
                ans += query(bit, n) - query(bit, curr - 1) + query(bit, t);
            }
            update(bit, n, t, -1);
            curr = t;
        }
        return ans;
    }

    private void update(int[] bit, int n, int idx, int delta) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
    }

    private int query(int[] bit, int idx) {
        int s = 0;
        for (; idx > 0; idx -= idx & -idx) s += bit[idx];
        return s;
    }
}

